<?php
declare(strict_types=1);
namespace App\Services;
use PDO; use RuntimeException;
final class RegistrationValidationService { public function __construct(private PDO $db) {} public function validate(int $tournamentId,int $teamId,int $personId): void { $r=(new RuleConfigurationService($this->db))->active($tournamentId);$p=$this->db->prepare('SELECT birth_date FROM people WHERE id=? AND deleted_at IS NULL');$p->execute([$personId]);$person=$p->fetch();if(!$person)throw new RuntimeException('Pessoa inválida.');$count=$this->db->prepare('SELECT COUNT(*) FROM registrations WHERE tournament_id=? AND team_id=? AND status="approved" AND deleted_at IS NULL');$count->execute([$tournamentId,$teamId]);if((int)$count->fetchColumn()>=$r['registration']['max_players'])throw new RuntimeException('Limite de elenco atingido.');$dup=$this->db->prepare('SELECT COUNT(*) FROM registrations WHERE tournament_id=? AND person_id=? AND deleted_at IS NULL AND status NOT IN ("rejected","cancelled")');$dup->execute([$tournamentId,$personId]);if((int)$dup->fetchColumn())throw new RuntimeException('Pessoa já inscrita no campeonato.');if(!empty($r['registration']['required_documents'])){$docs=$this->db->prepare('SELECT COUNT(*) FROM person_documents WHERE person_id=? AND status="approved" AND deleted_at IS NULL');$docs->execute([$personId]);if((int)$docs->fetchColumn()<count($r['registration']['required_documents']))throw new RuntimeException('Documentos obrigatórios ausentes.');} } }
